<?php if ($cases === []): ?><p class="empty"><?= e(__('empty.cases')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(__('fields.number')) ?></th><th><?= e(__('fields.document_title')) ?></th><th><?= e(__('fields.country_id')) ?></th><th><?= e(__('fields.status')) ?></th></tr></thead><tbody><?php foreach ($cases as $case): ?><tr><td data-label="Number"><a href="<?= e(url('/portal/applications/' . $case['id'])) ?>"><?= e($case['number']) ?></a></td><td data-label="Document"><?= e($case['document_title']) ?></td><td data-label="Country"><?= e($case['country_name'] ?? '') ?></td><td data-label="Status"><?= status_badge($case['status_name'] ?: $case['status_code'], $case['badge_tone']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
